/** Remove dependencies, build outputs and caches regenerated by project tooling. */
import { readdirSync, rmSync } from 'node:fs';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const DISPOSABLE = new Set(['node_modules', 'dist', 'build', 'coverage', '.cache', '.bds', '.bedrock-core']);
const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');

let removed = 0;

function drop(target) {
  const local = relative(root, resolve(target));

  if (!local || local === '..' || local.startsWith(`..${sep}`) || isAbsolute(local)) {
    throw new Error(`Clean target is outside the repository: ${target}`);
  }

  rmSync(target, { recursive: true, force: true });
  console.log(`removed ${local}`);
  removed++;
}

function sweep(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const target = join(dir, entry.name);

    if (entry.isSymbolicLink() || entry.name === '.git') { continue; }

    if (entry.isDirectory()) {
      if (DISPOSABLE.has(entry.name)) { drop(target); continue; }

      sweep(target);
    }
  }
}

sweep(root);
console.log(removed === 0 ? 'nothing to remove' : `${removed} ${removed === 1 ? 'path' : 'paths'} removed`);
